head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/etn_newlisting.js");
scwin.vScrenID = "ULDSTF08113.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo;
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fn_GetPar, scwin.fn_SetPar, scwin.fr_SecuGrpId;
scwin.pIndex;
scwin.TR_JOB;
scwin.notiId;
scwin.vDelCheck = "N";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_ISU_CD.getValue(); // 발행기관코드값
    arrPar[1] = txb_ISU_CD_NM.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    arrPar[3] = "9"; // 회사코드팝업 전체데이터
    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
    }
};
scwin.fn_initForm = function(gubnVal) {

};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(edt_EXPS_RTO) == "") {
        $c.win.alert("[제비용]를 입력하세요.");
        edt_EXPS_RTO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_HPAGE) == "") {
        $c.win.alert("[홈페이지]를 입력하세요.");
        txb_HPAGE.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_ETN_PROD_INFO) == "") {
        $c.win.alert("[상품정보(기본정보)]를 입력하세요.");
        txa_ETN_PROD_INFO.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_ETN_INVSTWARN_CONTN) == "") {
        $c.win.alert("[상품정보(투자유의사항)]를 입력하세요.");
        txa_ETN_INVSTWARN_CONTN.focus();
        return false;
    }
    return true;
};
scwin.fn_SetValue = function() {
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Item.setCellData(1, "EXPS_RTO", $c.stf.getObjectValue(edt_EXPS_RTO));
    dts_Item.setCellData(1, "HPAGE", $c.stf.getObjectValue(txb_HPAGE));
    dts_Item.setCellData(1, "ETN_PROD_INFO", $c.stf.getObjectValue(txa_ETN_PROD_INFO));
    dts_Item.setCellData(1, "ETN_INVSTWARN_CONTN", $c.stf.getObjectValue(txa_ETN_INVSTWARN_CONTN));
    dts_Item.setCellData(1, "DISTR_PAY_BAS_DD_ENG_CONTN", $c.stf.getObjectValue(txa_DISTR_PAY_BAS_DD_ENG_CONTN));
    dts_Item.setCellData(1, "ETN_ENG_PROD_INFO", $c.stf.getObjectValue(txa_ETN_ENG_PROD_INFO));
    dts_Item.setCellData(1, "ETN_ENG_INVSTWARN_CONTN", $c.stf.getObjectValue(txa_ETN_ENG_INVSTWARN_CONTN));
};
scwin.fn_trs = function(trsIdx) {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB == 'D') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }

    //alert('trsIdx:'+trsIdx);
    trs_Save.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveNewListingEtnSangpumInfoMgr";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Parameters = "TRS_IDX=" + trsIdx + ",BZ_PROCS_NO=" + scwin.vBzProcsNo;
    trs_Save.Post();
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        //dts_Item.UserStatus(1) = TB_JOB_INSERT;
        dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        scwin.fn_trs(TR_JOB_INSERT);
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if ($c.en.fn_CheckForm()) {
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        scwin.fn_trs(TR_JOB_UPDATE);
    }
};
scwin.fn_read_sync = function() {
    var url = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral&inputMessageId=ETN_SANGPUM_INFO_MGR_INOUT" + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.reset();
};
scwin.fn_saveFile = function() {
    var fileYn = "N";
    for (i = 1; i <= dts_Etn_File.getTotalRow(); i++) {
        if (dts_Etn_File.getCellData(i, "ATTACH_FILE_NM") != "") {
            fileYn = "Y";
        }
    }
    if (fileYn == "N") {
        $c.win.alert("첨부파일을 하나이상 등록해주세요");
        return;
    }
    trs_SaveAddFile.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02 + "&method=CreateEtnDrvClssAddFile&bz_procs_no=" + scwin.vBzProcsNo;
    trs_SaveAddFile.KeyValue = "JSP(I:pFile=dts_Etn_File)";
    trs_SaveAddFile.Post();
};
scwin.fn_updateFile = function() {
    if (dts_Etn_File.getTotalRow() == 0) {
        $c.win.alert("첨부파일을 한개이상  입력해주세요.");
        return;
    }
    trs_UpdateAddFile.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03 + "&method=modifyEtnDrvClssAddFile&bz_procs_no=" + scwin.vBzProcsNo;
    trs_UpdateAddFile.KeyValue = "JSP(I:pInput2=dts_Etn_File)";
    trs_UpdateAddFile.Post();
};
scwin.fn_deleteFile = function() {

    //dts_delEtnAddFile.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_delEtnAddFile.insertRow();
    dts_delEtnAddFile.setCellData(1, "bz_procs_no", scwin.vBzProcsNo);
    trs_DeleteAddFile.Action = "/etn/EtnNewList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04 + "&method=deleteEtnDrvClssAddFile";
    trs_DeleteAddFile.KeyValue = "JSP(I:pInput=dts_delEtnAddFile)";
    trs_DeleteAddFile.Post();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.scwin.vBzProcsNo;
    txb_ISU_CD.setValue(parentWin.txb_SearchIsuCd.getValue());
    txb_ISU_NM.setValue(parentWin.txb_SearchIsuNm.getValue());
    $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo); // 상품정보관리 첨부파일 조회

    scwin.fn_read_sync();
    if (dts_Item.getTotalRow() == 0) {
        dts_Item.insertRow();
        btn_save.src = "../img/btn_save.gif";
        btn_save.setDisabled(false);
        btn_Update.src = "../img/btn_modify_d.gif";
        btn_Update.setDisabled(true);
    } else {
        btn_save.src = "../img/btn_save_d.gif";
        btn_save.setDisabled(true);
        btn_Update.src = "../img/btn_modify.gif";
        btn_Update.setDisabled(false);
    }
    edt_EXPS_RTO.focus();
};
scwin.btn_save_onclick = function() {
    scwin.fn_save();
};
scwin.btn_Update_onclick = function() {
    scwin.fn_update();
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnSuccess = function() {
    $c.lce.fn_alertMsg('S');
    btn_save.src = "../img/btn_save_d.gif";
    btn_save.setDisabled(true);
};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.txa_ETN_INVSTWARN_CONTN_OnKillFocus = function() {
    edt_EXPS_RTO.focus();
};
scwin.grd_Fil_OnDblClick = function(row, colid) {
    if (dts_Etn_File.getRowStatus(dts_Etn_File.getRowPosition()) == 0) {
        $c.en.fn_prodInfo_filedown(dts_Etn_File, dts_Etn_File.getCellData(row, "BZ_PROCS_NO"));
    }
};
scwin.btn_lineadd_onclick = function() {
    var rtn = confirm('첨부파일을 추가 하시겠습니까?');
    if (rtn == 1) {
        if (dts_Etn_File.getTotalRow() >= 30) {
            // 첨부파일 갯수 처리(30개)
            $c.win.alert("첨부파일은 최대 30개 입니다.");
            return;
        }
        dts_Etn_File.insertRow();
        inf_find.open();
        if (inf_find.getValue() != "") {
            if (scwin.notiId == "input") {
                dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
                scwin.fn_saveFile();
            } else {
                dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
                dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_SEQ", dts_Etn_File.getRowPosition());
                dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "BZ_PROCS_NO", scwin.vBzProcsNo);
                file_name.setValue(inf_find.getValue());
                scwin.fn_updateFile();
            }
        } else {
            $c.cp.removeRow(dts_Etn_File, dts_Etn_File.getRowPosition());
        }
    }
};
scwin.btn_linedelete_onclick = function() {
    var rtn = confirm('첨부파일을 삭제 하시겠습니까?');
    if (rtn == 1) {
        // [확인] 버튼이 눌려졌을 경우
        $c.cp.removeRow(dts_Etn_File, dts_Etn_File.getRowPosition());
        if (dts_Etn_File.getTotalRow() == 0) {
            scwin.fn_deleteFile();
        } else {
            scwin.vDelCheck = "Y";
            if (scwin.notiId == "input") {
                scwin.fn_saveFile();
            } else {
                scwin.fn_updateFile();
            }
        }
    }
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_Etn_File.getCellData(dts_Etn_File.getRowPosition(), "filename");
    if (scwin.notiId == "input") {
        dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_FILE_NM", inf_find.getValue());
        dts_Etn_File.setCellData(dts_Etn_File.getRowPosition(), "ATTACH_SEQ", dts_Etn_File.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.trs_SaveAddFile_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 등록"));
    $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo);
};
scwin.trs_SaveAddFile_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 등록"));
};
scwin.trs_UpdateAddFile_OnSuccess = function() {
    if (scwin.vDelCheck == "N") {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 수정"));
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 삭제"));
    }
    $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo);
    scwin.vDelCheck = "N";
};
scwin.trs_UpdateAddFile_OnFail = function() {
    if (scwin.vDelCheck == "N") {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 수정"));
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 삭제"));
    }
};
scwin.trs_DeleteAddFile_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "첨부파일 삭제"));
    scwin.vDelCheck = "N";
    $c.en.fn_etnFile_prodInfo_read_sync(dts_Etn_File, scwin.vBzProcsNo);
};
scwin.trs_DeleteAddFile_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "첨부파일 삭제"));
};
